  ('EAC', 'high_school', '{"title":"ผู้บริหารแบรนด์","summary":"คุณกล้าตัดสินใจ มีไอเดียสร้างสรรค์ และจัดการทุกอย่างให้เป็นระบบ คุณเหมาะกับงานที่ต้องดูแลภาพลักษณ์ แผนงาน และตัวเลขไปพร้อมกัน เพื่อให้งานสร้างสรรค์เติบโตอย่างมั่นคง","strengths":[{"title":"มองภาพลักษณ์ได้ขาด","detail":"รู้ว่าอะไรเข้ากับแบรนด์และอะไรไม่ใช่"},{"title":"วางแผนและคุมงบ","detail":"ทำให้ไอเดียเกิดขึ้นได้ในงบที่มี"},{"title":"ตัดสินใจอย่างมั่นใจ","detail":"เลือกทางเมื่อมีหลายตัวเลือกได้เร็ว"},{"title":"ทำงานเป็นระบบ","detail":"ติดตามทุกงานจนเสร็จตามกำหนด"}],"careers":[{"title":"ผู้จัดการแบรนด์","reason":"ดูแลภาพลักษณ์และแผนการตลาดของแบรนด์ให้สอดคล้องกัน","tag":"นำทีม • สร้างสรรค์"},{"title":"ผู้ซื้อสินค้าแฟชั่น (buyer)","reason":"เลือกสินค้าที่เข้ากับแบรนด์และคุมงบซื้ออย่างแม่นยำ","tag":"สร้างสรรค์ • จัดระบบ"},{"title":"ผู้จัดการร้านค้าแฟชั่นและไลฟ์สไตล์","reason":"ดูแลการจัดร้าน ยอดขาย และทีมให้ไปในทางเดียวกัน","tag":"นำทีม • สร้างสรรค์"},{"title":"นักวางแผนสื่อโฆษณา","reason":"เลือกช่องทางและงบโฆษณาให้ได้ผลคุ้มค่าที่สุด","tag":"นำทีม • จัดระบบ"},{"title":"โปรดิวเซอร์โฆษณาและวิดีโอ","reason":"คุมงบ เวลา และทีมให้งานสร้างสรรค์ออกมาตามแผน","tag":"นำทีม • จัดระบบ"},{"title":"ผู้จัดการฝ่ายการตลาดสินค้า","reason":"วางแผนการเปิดตัวสินค้าและติดตามยอดขาย","tag":"นำทีม • จัดระบบ"}],"guidance":[{"title":"การตลาด","tag":"บริหารธุรกิจ","detail":"เรียนการเข้าใจผู้บริโภคและวางแผนแบรนด์จากข้อมูล","programs":[{"university":"มหาวิทยาลัยเกษตรศาสตร์","campus":"กำแพงแสน","faculty":"คณะศิลปศาสตร์และวิทยาศาสตร์","program":"บธ.บ. สาขาวิชาการตลาด","url":"https://course.mytcas.com/programs/10020222610601A","fieldUrl":"https://course.mytcas.com/universities/002/faculties/22/fields/06","rounds":["รอบ 2","รอบ 3"]},{"university":"มหาวิทยาลัยพะเยา","campus":"วิทยาเขตหลัก","faculty":"คณะบริหารธุรกิจและนิเทศศาสตร์","program":"หลักสูตรบริหารธุรกิจบัณฑิต สาขาวิชาการตลาดดิจิทัล","url":"https://course.mytcas.com/programs/10270107610601A","fieldUrl":"https://course.mytcas.com/universities/027/faculties/07/fields/06","rounds":["ร